<?php declare(strict_types=1);namespace App\Controllers;use App\Core\Controller;use App\Models\ToolRun;use App\Services\AuthService;final class DashboardController extends Controller{public function user():void{$u=(new AuthService($this->db))->user();$runs=(new ToolRun($this->db))->recent((int)$u['id']);$this->view('user.dashboard',['title'=>'Dashboard','user'=>$u,'runs'=>$runs]);}public function admin():void{$stats=['users'=>$this->db->fetch('select count(*) c from users')['c']??0,'runs'=>$this->db->fetch('select count(*) c from tool_runs')['c']??0,'plugins'=>$this->db->fetch('select count(*) c from plugins')['c']??0];$this->view('admin.dashboard',['title'=>'Admin Dashboard','stats'=>$stats]);}}
